import { readFile, writeFile } from 'node:fs/promises';
import { fileURLToPath } from 'node:url';
import openapiTS, { astToString } from 'openapi-typescript';

const contractUrl = new URL('../docs/buyeros/contracts/openapi.proposed.yaml', import.meta.url);
const outputUrl = new URL('../services/generated/buyeros-api.ts', import.meta.url);
const header = `/**
 * This file was auto-generated by openapi-typescript.
 * Do not make direct changes to the file.
 */

`;
const mode = process.argv[2];

if (mode !== '--check' && mode !== '--write') {
  console.error('usage: node scripts/generate-api-types.mjs --check|--write');
  process.exit(2);
}

const generated = header + astToString(await openapiTS(contractUrl));
const current = await readFile(outputUrl, 'utf8').catch((error) => {
  if (error.code === 'ENOENT') return null;
  throw error;
});
const normalize = (value) => value?.replaceAll('\r\n', '\n');

if (mode === '--check') {
  if (normalize(current) !== normalize(generated)) {
    console.error(`API types are stale: ${fileURLToPath(outputUrl)}`);
    process.exit(1);
  }
  console.log('API types match the OpenAPI contract');
} else {
  const newline = current?.includes('\r\n') ? '\r\n' : '\n';
  await writeFile(outputUrl, generated.replaceAll('\n', newline), 'utf8');
  console.log(`Wrote ${fileURLToPath(outputUrl)}`);
}
